struct Counter { n: u32 }
impl Counter {
    fn new() -> Self { Counter { n: 0 } }
    fn inc(&mut self) { self.n += 1; }
    fn get(&self) -> u32 { self.n }
}
fn main() {
    let mut c = Counter::new();
    c.inc();
    println!("{}", c.get());
}

