enum Shape {
    Circle(f64),
    Rect(f64, f64),
}
fn area(s: &Shape) -> f64 {
    match s {
        Shape::Circle(r) => 3.14 * r * r,
        Shape::Rect(w, h) => w * h,
    }
}
fn main() {
    println!("{}", area(&Shape::Rect(2.0, 3.0)));
}

fn find(v: &[i32], x: i32) -> Option<usize> {
    v.iter().position(|&n| n == x)
}
fn main() {
    match find(&[5, 6, 7], 6) {
        Some(i) => println!("at {i}"),
        None => println!("missing"),
    }
    if let Some(i) = find(&[1], 9) { println!("{i}"); }
}

use std::num::ParseIntError;
fn double(s: &str) -> Result<i32, ParseIntError> {
    let n: i32 = s.parse()?;
    Ok(n * 2)
}
fn main() {
    println!("{:?}", double("21"));
    println!("{:?}", double("x").is_err());
}

